public class Main {
    public static void main(String[] args) throws Exception {
        String s = new FastReader().next();
        int n = s.length(), last = -1, keep = n;
        char first = s.charAt(0), end = s.charAt(n - 1);
        for (int j = 0; j < n; j++) {
            char c = s.charAt(j);
            if (c == first) last = j;  // nearest original first character so far
            if (c == end && last >= 0) keep = Math.min(keep, j - last + 1);
        }
        System.out.println(n - keep);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

